// --- system under test: encode an int to a string, decode back ---
function encode(n) {
  // BUG: negative numbers lose their sign in this naive scheme
  return 'i' + Math.abs(n) + 'e';
}
function decode(s) {
  return parseInt(s.slice(1, -1), 10);
}

// --- deterministic seeded generator: mulberry32 (no Math.random) ---
function mulberry32(a) {
  return function () {
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
function genInt(rnd) {
  // range [-500, 499] so negatives are well represented
  return Math.floor(rnd() * 1000) - 500;
}

// --- naive shrinker: walk the failing int toward 0 ---
function shrink(n, fails) {
  let best = n;
  let step = n > 0 ? -1 : 1;
  while (best !== 0 && fails(best + step)) best += step;
  return best;
}

// --- property runner ---
function checkRoundTrip(runs, seed) {
  const rnd = mulberry32(seed);
  const fails = (x) => decode(encode(x)) !== x;
  for (let i = 0; i < runs; i++) {
    const x = genInt(rnd);
    if (fails(x)) {
      const minimal = shrink(x, fails);
      console.log('FAIL after ' + (i + 1) + ' cases. counterexample: ' + minimal + ' (seed ' + seed + ')');
      return;
    }
  }
  console.log('all ' + runs + ' cases pass');
}

checkRoundTrip(200, 42);
